package com.example.assets_management.security.service;
import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.userdetails.UserDetails; import java.util.*;
public final class CustomUserDetails implements UserDetails { private final UUID userId,companyId,branchId,departmentId,roleId; private final String email,employeeCode,passwordHash,roleName; private final boolean enabled; private final Collection<? extends GrantedAuthority> authorities;
 public CustomUserDetails(UUID userId,String email,String employeeCode,String passwordHash,UUID companyId,UUID branchId,UUID roleId,String roleName,boolean enabled,Collection<? extends GrantedAuthority> authorities){ this(userId,email,employeeCode,passwordHash,companyId,branchId,null,roleId,roleName,enabled,authorities);}
 public CustomUserDetails(UUID userId,String email,String employeeCode,String passwordHash,UUID companyId,UUID branchId,UUID departmentId,UUID roleId,String roleName,boolean enabled,Collection<? extends GrantedAuthority> authorities){this.userId=userId;this.email=email;this.employeeCode=employeeCode;this.passwordHash=passwordHash;this.companyId=companyId;this.branchId=branchId;this.departmentId=departmentId;this.roleId=roleId;this.roleName=roleName;this.enabled=enabled;this.authorities=authorities==null?List.of():List.copyOf(authorities);}
 public UUID getUserId(){return userId;} public String getEmployeeCode(){return employeeCode;} public UUID getCompanyId(){return companyId;} public UUID getBranchId(){return branchId;} public UUID getDepartmentId(){return departmentId;} public UUID getRoleId(){return roleId;} public String getRoleName(){return roleName;} public Collection<? extends GrantedAuthority> getAuthorities(){return authorities;} public String getPassword(){return passwordHash;} public String getUsername(){return email;} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return true;} public boolean isCredentialsNonExpired(){return true;} public boolean isEnabled(){return enabled;} }
